const themeHeader = 'Sec-CH-Prefers-Color-Scheme';

serverInit(req: IncomingMessage, res: ServerResponse) {
  const cookies = Cookie(req, res);

  const systemTheme = req.headers[
    themeHeader.toLowerCase()
  ] as SystemThemeName;
