describe('Mounting hello', () => {
  // ...
  it('can mount using composable', async () => {
    const i18n = createI18n({
      // vue-i18n options here ...
    })

    const component = await mountSuspended(HelloComposable, { global: {
      plugins: [i18n]
    }})

    expect(component.vm.toBeTruthy())

