import type { PostBySlug } from '@/types/strapi'
import { StrapiBlocks } from 'vue-strapi-blocks-renderer'

definePageMeta({
  layout: 'post',
})

const { locales } = useI18n()
const localePath = useLocalePath()

const setI18nParams = useSetI18nParams()

