        v-for="locale in availableLocales"
        :key="locale.code"
        class="first:ml-0 mx-2 btn btn-sm btn-info btn-outline"
        :to="switchTranslation(locale.code)"
      >{{ locale.flag }} {{ locale.name }}</NuxtLink>
    </div>
    <StrapiBlocks
      v-if="content"
      :content="content"
    />
  </article>
</template>
