```ts
import type { StorybookConfig } from '@nuxtjs/storybook'

const config: StorybookConfig = {
  framework: {
    name: '@storybook-vue/nuxt',
    options: {
      // docgen: 'vue-component-meta',
    },
  },
  stories: [
    // '../app/components/**/*.mdx',
    '../app/components/**/*.stories.@(js|jsx|ts|tsx|mdx)',
  ],
  addons: [
    '@chromatic-com/storybook',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
    // '@storybook/addon-vitest',
    // '@github-ui/storybook-addon-performance-panel/universal',
  ],
  viteFinal: async (config) => {
    const SERVER_WATCH_IGNORED = ['**/node_modules/**', /[\\/]node_modules[\\/]/, '**/.nuxt/analyze/**']
    config.server ??= {}
    config.server.watch = { ...config.server.watch, ignored: SERVER_WATCH_IGNORED }

    // NOTE: `nuxt:environments` plugin wipes `optimizeDeps.include`, which (with `noDiscovery: true`)
    // disables pre-bundling, so CJS-only deps required by addon-docs crash docs pages.
    // re-apply here for the client environment. keep the list minimal,
    // matching import specifiers verbatim, and resolvable from the project root (see devDependencies).

    const CLIENT_OPTIMIZE_DEPS = ['react', 'react/jsx-runtime', 'react-dom', 'react-dom/client', 'semver', 'use-sync-external-store/shim/index.js']
    config.plugins ??= []
    config.plugins.push({
      name: 'storybook:restore-client-optimizedeps',
      configEnvironment (name, envConfig) {
        if (name !== 'client') return
        envConfig.optimizeDeps ??= {}
        envConfig.optimizeDeps.include ??= []
        for (const dep of CLIENT_OPTIMIZE_DEPS) {
          if (envConfig.optimizeDeps.include.includes(dep)) return
          envConfig.optimizeDeps.include.push(dep)
        }
      },
    })

    return config
  },
  // core: {
  //   disableTelemetry: true,
  //   enableCrashReports: true,
  // },
  // features: {
  //   experimentalDocgenServer: true, // NOTE: enabling makes the props table to not render at all
  // },
}

export default config
```

