build: {
  extend: (config: any, ctx: any) => {
    ctx.loaders.scss ||= {}
    ctx.loaders.scss.sassOptions ||= {}
    if (typeof ctx.loaders.scss.sassOptions === 'object') {
      ctx.loaders.scss.sassOptions.silenceDeprecations = [
        'global-builtin',
        'import',
        'legacy-js-api',
        'color-functions',
      ]
    }
  },
},
````
but Style Resources should be adapted to get Dart Sass 3 compatibility.

