My current workaround:

Note that the original defineCollection doesn't return the original schema.
https://github.com/nuxt/content/blob/e6bf06f02e594a628665dfb4a63778ebf2b3a54c/src/utils/collection.ts#L14-L39

So first step, we need to append the original schema to the defined collection.

```ts
// content.config.ts

import { defineCollection, defineContentConfig } from '@nuxt/content'

import { productSchema } from './content/schemas/product'

import type { Collection, DefinedCollection } from '@nuxt/content'

// Wrap defineCollection and append originalSchema to it
const defineCollectionWithOriginalSchema = <T>(collection: Collection<T>): (
  DefinedCollection & { originalSchema: Collection<T>['schema'] }
) => ({
  ...defineCollection(collection),
  originalSchema: collection.schema,
})

export default defineContentConfig({
  collections: {
    product: defineCollectionWithOriginalSchema({
      type: 'data',
      source: 'product/*.yaml',
      schema: productSchema,
    }),
  },
})
```

And then within `nuxt.config.ts`, we can use the [`content:file:afterParse` hook](https://content.nuxt.com/docs/advanced/hooks#contentfileafterparse) to do validation during build time.

```ts
// nuxt.config.ts
import z from 'zod'

import type { ResolvedCollection } from '@nuxt/content'
import type { ZodType } from 'zod'

// https://nuxt.com/docs/api/configuration/nuxt-config
export default defineNuxtConfig({
  // Other config

  hooks: {
    'content:file:afterParse': ({ content, collection }) => {
      const schema = (collection as ResolvedCollection & { originalSchema: ZodType | undefined }).originalSchema
      schema?.parse(content)

      // or if you want to format error, you can use the following.

      // if (!schema) return

      // const parseResult = schema.safeParse(content)
      // if (!parseResult.success) {
      //  throw new Error(`\n${z.prettifyError(parseResult.error)}`)
      // }
    },
  },
})
```

However, since any error in the hook will be catched and be passed to `logger.warn`, so we need to check the log of `nuxt dev` / `nuxt build` to see if there is any error.

Or we can just use a more aggressive `process.exit` to make it easier to be noticed.

