  (e: "load", data: any): void
}

interface Props extends /* @vue-ignore */ NuxtPictureProps {
  src?: string
  fallback?: string
}

const emit = defineEmits<Emits>()

const props = defineProps<Props>()

const attrs = useAttrs()

const propsWithoutFallbackAndSrc = computed(() => {
