import { joinURL, encodeQueryItem } from 'ufo';
import { createOperationsGenerator, defineProvider } from '@nuxt/image/runtime';

const operationsGenerator = createOperationsGenerator({
  keyMap: {
    width: 'w',
    height: 'h',
    dpr: 'dpr',
    fit: 'fit',
    gravity: 'g',
    quality: 'q',
    format: 'f',
    sharpen: 'sharpen',
  },
  valueMap: {
    fit: {
      cover: 'cover',
      contain: 'contain',
      fill: 'scale-down',
      outside: 'crop',
      inside: 'pad',
    },
    gravity: {
      auto: 'auto',
      side: 'side',
    },
  },
  joinWith: ',',
  formatter: (key, val) => encodeQueryItem(key, val),
});

export default defineProvider({
  getImage(imageId: string, { modifiers }) {
    const operations = operationsGenerator(modifiers);

    const accountHash = useRuntimeConfig().public.images.cloudflareAccountHash;
