Here's a very hacky workaround that I'm using :

prerender.mjs

```ts
import { appendHeader } from "h3";
import { useRequestEvent } from "#imports";

export function prerenderStaticImages(src = "", srcset = "") {
  if (!process.server || !process.env.prerender) {
    return;
  }
  const paths = [
    src,
    ...srcset.split(", ").map((s) => s.trim().split(" ")[0].trim())
  ].filter((s) => s && s.includes("/_ipx/"));
  if (!paths.length) {
    return;
  }
  appendHeader(
    useRequestEvent(),
    "x-nitro-prerender",
    paths.map((p) => encodeURIComponent(p)).join(", ")
  );
  

  const writeStaticImages = async () => {
    const stream = await import("node:stream");
    const util = await import("node:util");
    const nodePath = await import("node:path");
    const url = await import("node:url");
    const fs = await import("node:fs");
  
    const __filename = url.fileURLToPath(import.meta.url);
    const __dirname = nodePath.dirname(__filename);
  
    const publicDirectory = nodePath.join(__dirname, "../../public/");
    
    // Function to handle a single path
    const handlePath = async (path) => {
      try {
        const url = "http://localhost:3000" + path;
        console.log("Downloading ", path, url);
        const response = await fetch(url);
        if (!response.ok) throw new Error("Couldn't download ...", response.error);
        const location = nodePath.join(publicDirectory, path);
        console.log(`Writing to location ${location}, Dirname ${__dirname}, Path ${path}`);
  
        await fs.promises.mkdir(nodePath.dirname(location), { recursive: true });
  
        await util.promisify(stream.pipeline)(
          response.body,
          fs.createWriteStream(location)
        );
      } catch (e) {
        console.error(e);
      }
    };
  
    // Split paths into chunks of 10
    const chunks = [];
    for (let i = 0; i < paths.length; i += 10) {
      chunks.push(paths.slice(i, i+10));
    }
  
    // Process each chunk one by one
    for (const chunk of chunks) {
      // Process all paths in the current chunk concurrently
      await Promise.all(chunk.map(handlePath));
    }
  };
  
  writeStaticImages()
}
```

Run the build with the dev server opened in parallel, this will download all images and add write them in /public, and Nitro will correctly resolves them as static assets.

