@1nusah Sorry, I meant a `ttl` option. It shouldn't be on by default I'd say.

Congrats to all the ideas. But still hoping we get an official out of the box implementation.
Until `ttl` is coming, I used something like this:

```JS
const ttl = (cacheDuration = 0) => ({
	transform: input => ({...input, cachedAt: new Date()}),
	getCachedData: (key, nuxtApp) => {
		const data = nuxtApp.payload.data[key] || nuxtApp.static.data[key]

		// no data
		if (!data) return 
		
		// data too old (cacheDuration = 0, means permaCache (until page is refreshed))
		if (cacheDuration && data.cachedAt?.getTime() < new Date().getTime() - cacheDuration) return 
		
		return data
	}
})

const { data, status } = await useFetch(() => `/api/stats/player?id=${uid}`, {
	key: `/api/stats/player?id=${uid}`,
	lazy: true,
	server: false,
	...ttl(300 * 1000)
})
```

Where `ttl` is a composable so you have access to it from everywhere. Works like a charm; and at least I don't have to do the abomination extra code each time I need it (and i need it a lot)

mmm maybe try this one? It is safe to use with lazy: true and server: true

```
// utils/cache.config.js

export const cacheDurations = {
	defaultMs: 30000, // 30 secs
	durations: {
		"foo-key": 120000,
		"bar-key": 50000
	}
}

```

```// composables/useTimedFetch.js
// composables/useTimedFetch.js

import { cacheDurations } from "~/utils/cache.config"

export function useTimedFetch(url, opts = {}) {
	const nuxtApp = useNuxtApp()

	// meta = { [key]: { ts, ttl } }
	// Holds metadata for each cache key, including timestamp and TTL duration
	const meta = useState("__cache_meta__", () => ({}))

	// clientCache = { [key]: any }
	// Stores cached responses in memory for client-side reuse
	const clientCache = useState("__client_cache__", () => ({}))

	// hydration flag: during the first client render, always trust SSR payload data
	const hydrating = useState("__hydrating__", () => true)

	// Determine cache duration from config or fallback to default
	const duration =
		cacheDurations.durations?.[opts.cacheKey] ?? cacheDurations.defaultMs

	const HYDRATION_BUFFER = 10000 // 10s safety buffer to avoid hydration mismatch

	const fetcher = useFetch(url, {
		dedupe: "defer", // Combine simultaneous requests with the same key
		// IMPORTANT: when using lazy, payload is empty on SSR; clientCache compensates for it
		...opts,
		getCachedData(key) {
			// 1) Try to get data from SSR payload / static cache
			const fromPayload =
				nuxtApp.payload?.data?.[key] || nuxtApp.static?.data?.[key]
			// 2) Try to get data from client-side memory cache
			const fromClient = clientCache.value?.[key]

			const cached = fromPayload ?? fromClient
			if (!cached) return null

			// During initial hydration, if SSR payload exists, always use it
			if (process.client && hydrating.value && fromPayload) {
				return fromPayload
			}

			// Retrieve metadata for the given cache key
			const m = meta.value[key]
			// If no metadata yet (first cache), allow it once
			if (!m) return cached

			// Check if the cached data is still fresh
			const fresh = Date.now() - m.ts < (m.ttl ?? duration) - HYDRATION_BUFFER
			return fresh ? cached : null
		},
		onResponse({ options, response }) {
			const k = typeof options?.key === "function" ? options.key() : options?.key
			if (!k) return

			// Store metadata (never mutate actual response data)
			meta.value[k] = { ts: Date.now(), ttl: duration }

			// Save response data into client-side memory cache
			if (response?._data !== undefined) {
				clientCache.value[k] = response._data
			}
		}
	})

	if (process.client) {
		onMounted(() => {
			hydrating.value = false

			// After hydration: if cache expired, silently refresh it in the background
			const k = typeof opts.key === "function" ? opts.key() : opts.key
			const m = k ? meta.value[k] : null
			if (!m) return
			const expired = Date.now() - m.ts >= m.ttl
			if (expired) fetcher.refresh()
		})
	}

	return fetcher
}
```

Simple Usage

```
// Fetch Data
	const {
		data,
		error,
		status
	} = await useTimedFetch({url}, {
		method: "GET",
		key: "my-unique-key",
		cacheKey: "foo-key", // 120.000 ms
		lazy: true,
	})
```

