## 2. Custom error handler
```ts
// ~/handler/errorHandler

import { NitroErrorHandler } from "nitropack";
import { H3Error, H3Event } from "h3";

const handler: NitroErrorHandler = (error: H3Error, event: H3Event) => {
  setResponseHeader(event, "Content-Type", "application/json");
  // console.log(">>> error", JSON.stringify(error));

  // BSONerror
  if (error.cause?.constructor.name === "BSONError") {
    setResponseStatus(event, 400, "Invalid ObjectId.");
  }
  // IO-TS error
  else if (error?.cause?.constructor.name === "DecodeError") {
    setResponseStatus(event, 400, "Invalid data structure.");
  }
  // Unhandled error
  else {
    setResponseStatus(event, error.statusCode, error.statusMessage); 
  }

  return send(
    event,
    JSON.stringify({
      ok: false,
      message: error.statusMessage,
    })
  );
};

export default defineNitroErrorHandler(handler);
```

## 3. Throw application runtime error
```ts
import { PathReporter } from "io-ts/lib/PathReporter.js";

async function useBodyValidator(
  event: any,
  schema: any
): Promise<null | any> {
  const body = await readBody(event);
  const decode = schema.decode(body);

  if (decode._tag === "Right") {
    return decode.right;
  } else {

    // handle the error in custom error handler
    throw createError({
      name: "DecodeError",
      statusCode: 400,
      statusMessage:
        "Invalid data structure. " + PathReporter.report(decode).join(". "),
    });
  }
}

// ... application logic 
```


