My specific use case is:
- We have our normal landingpage
- We also have our "portal"/panel for users to manage stuff concerning their site
- We also host their site for them, which all of this logic handles the routing for

app/router.options.ts
```ts
import type { RouterOptions } from "@nuxt/schema";
import type { RouteRecordRaw } from "vue-router";

const tenantDynamicRoute = "businessId";

const rewritePrefixRoute = (route: RouteRecordRaw) => {
  if (route.path.startsWith(`/:${tenantDynamicRoute}()`)) {
    return {
      ...route,
      path: route.path.replace(`/:${tenantDynamicRoute}()`, ""),
    };
  }

  return route;
};

const filterForTenantRoutes = (route: RouteRecordRaw, inverse = false) => {
  return inverse
    ? !route.path.startsWith(`/:${tenantDynamicRoute}()`)
    : route.path.startsWith(`/:${tenantDynamicRoute}()`);
};

export default <RouterOptions>{
  routes: async routes => {
    if (process.env.NODE_ENV === "development") {
      return routes;
    }

    let tenant;
    if (import.meta.server) {
      const event = useRequestEvent();
      tenant = event?.context?.tenant;
    } else {
      tenant = useNuxtApp().payload.tenant;
    }

    if (!tenant) {
      // no custom domain / tenant at all
      return routes.filter(route => filterForTenantRoutes(route, true));
    } else {
      return routes
        .filter(route => filterForTenantRoutes(route, false))
        .map(rewritePrefixRoute);
    }
  },
};
```

