```ts
import { rootDomains } from "~/utils/consts";
import {
  validateTenantFromHostname,
  validateDevBusinessId,
} from "~/server/utils/tenant-validation";

export default defineEventHandler(async event => {
  try {
    const { hostname, pathname } = getRequestURL(event);
    const runtimeConfig = useRuntimeConfig(event);

    const rootDomain = rootDomains.find(domain => hostname.endsWith(domain));
    const isDevelopment = process.env.NODE_ENV === "development";
    const isLocalhost = hostname === "localhost";
    const isVercel = hostname.endsWith(".vercel.app");

    // Try development business ID validation first, then fallback to hostname
    const response =
      (isDevelopment &&
        isLocalhost &&
        (await validateDevBusinessId(pathname, runtimeConfig))) ||
      (await validateTenantFromHostname(hostname, runtimeConfig));

    const tenantData = response?.tenantData || null;

    // Check if we should throw 404 (only for non-development hostname failures)
    const subdomain = hostname.substring(
      0,
      hostname.indexOf(rootDomain ?? "") - 1
    );

    const shouldThrow404 =
      !response.isValid &&
      rootDomain !== hostname &&
      subdomain !== "restaurant" &&
      !isDevelopment &&
      !isLocalhost &&
      !isVercel;

    if (shouldThrow404) {
      throw createError({
        statusCode: 404,
        statusMessage: `Domain "${hostname}" not found`,
      });
    }

    event.context.tenant = tenantData;
  } catch (error) {
    console.error("Error in tenancy plugin:", error);

    // Re-throw if it's already a createError (like our 404)
    if (error && typeof error === "object" && "statusCode" in error) {
      throw error;
    }
  }
});
```

composables/useTenant.ts
(the `/api/tenant/revalidate` route, returns data in the same format/manner as the global tenancy middleware)
```ts
import type { TenantData } from "~/server/utils/tenant-validation";

export const useTenant = () => {
  // Use useState to access the shared server/client data
  const { payload } = useNuxtApp();
  const route = useRoute();

  // Access the global tenant state managed by server middleware
  const tenant = useState<TenantData | null>(
    "tenant",
    () => payload.tenant as TenantData | null
  );

  // Watch for route changes in development mode (client-side only)
  if (import.meta.client) {
    const isDevelopment = process.env.NODE_ENV === "development";
    const isLocalhost = window.location.hostname === "localhost";

    if (isDevelopment && isLocalhost) {
      // Watch for route changes and let the API determine everything
      watch(
        () => route.path,
        async () => {
          try {
            // Just call the API - it will figure out the business ID from the URL
            const response = await $fetch<{
              isValid: boolean;
              tenantData: TenantData | null;
            }>("/api/tenant/revalidate", {
              method: "POST",
              body: {
                hostname: window.location.hostname,
                pathname: route.path,
              },
            });

            if (response.isValid && response.tenantData) {
              tenant.value = response.tenantData;
            } else {
              tenant.value = null;
            }
          } catch (error) {
            console.error("Failed to validate tenant on route change:", error);
            tenant.value = null;
          }
        },
        { immediate: false }
      );
    }
  }

  return tenant;
};
```

