utils/deepReadonly.ts
```
export default function deepReadonly<T>(obj: T): T {
  if (Array.isArray(obj))
    return obj.map(deepReadonly) as any

  if (obj !== null && typeof obj === 'object') {
    const result: any = {}
    for (const key in obj)
      result[key] = deepReadonly(obj[key])
    return readonly(result)
  }
  return obj
}
```

