I tried adding the assets directory to publicAssets and Nitro does serve the files, but unfortunately with the wrong MIME type (application/json instead of application/javascript).
Overriding Nitro's MIME type handling would require more workarounds than it's worth. The middleware solution I suggested is cleaner and gives us direct control over both serving the files and setting the correct content type.
The only part we need to add in `configureServer` is the follow:

```typescript
async configureServer (viteServer) {
      // Serve worker assets from node_modules
      viteServer.middlewares.use(async (req, res, next) => {
        if (req.url?.includes('/assets/') && req.url?.includes('worker') && req.url?.endsWith('.js')) {
          const fs = await import('node:fs')
          const { join } = await import('pathe')

          const searchPaths = [
            join(nuxt.options.rootDir, 'node_modules'),
            join(nuxt.options.workspaceDir, 'node_modules'),
            ...nuxt.options.modulesDir,
          ]

          for (const basePath of searchPaths) {
            if (!fs.existsSync(basePath)) { continue }

            const packages = fs.readdirSync(basePath)
            for (const pkg of packages) {
              if (pkg.startsWith('.')) { continue }

              const pkgPath = pkg.startsWith('@') ? basePath : join(basePath, pkg)
              const workerPath = join(pkgPath, pkg.startsWith('@') ? pkg : 'dist', req.url)

              if (fs.existsSync(workerPath)) {
                const content = await fs.promises.readFile(workerPath, 'utf-8')
                res.setHeader('Content-Type', 'application/javascript; charset=utf-8')
                res.end(content)
                return
              }
            }
          }
        }
        next()
      })

// .... other stuff
```

I also ran into this issue and built myself a workaround via the 'prepare:types' hook in the nuxt.config.ts:

```ts
hooks: {
  // Order layer aliases to the top in tsconfig.json so that IDEs suggest
  // them first over the generic '~~' alias.
  'prepare:types'({ tsConfig }) {
    if (!tsConfig.compilerOptions) return;

    const tsConfigPaths = Object.entries(
      tsConfig.compilerOptions.paths as Record<string, string[]>,
    );

    const pathGroups = Object.groupBy(
      tsConfigPaths,
      ([_, pathValues]) =>
        pathValues.some((pathValue) =>
          pathValue.includes('/layers/'),
        )
          ? 'layers'
          : 'other',
    );
    tsConfig.compilerOptions.paths = Object.fromEntries([
      ...(pathGroups.layers ?? []),
      ...(pathGroups.other ?? []),
    ]);
  },
},
```

