Hi! You can resolve plugins order yourself with `app:resolve` hook
Here the module to run all number-prefixed plugins (sorted) after non-prefixed:

```

export default defineNuxtModule({
    meta: {
        name: 'plugins-order',
    },
    defaults: {},
    setup(options, nuxt) {
        nuxt.hook('app:resolve', (app) => {
            app.plugins.sort((a, b) => {
                const aName = ensureName(a.src.split('/').pop())
                const bName = ensureName(b.src.split('/').pop())

                if (!aName.match(/^[0-9]+/) && !bName.match(/^[0-9]+/)) {
                    return 0
                }
                if (!aName.match(/^[0-9]+/) && bName.match(/^[0-9]+/)) {
                    return -1
                }
                if (aName.match(/^[0-9]+/) && !bName.match(/^[0-9]+/)) {
                    return 1
                }
                if (aName.match(/^[0-9]+/) && bName.match(/^[0-9]+/)) {
                    if (aName < bName) {
                        return -1
                    }
                    if (aName > bName) {
                        return 1
                    }
                    return 0
                }
                return 0
            })
        })
    },
})

function ensureName(name) {
    const namesMap = {
        'plugin-to-be-last.js': '99.plugin-to-be-last.js',
        'plugin-to-be-first.js': '00.plugin-to-be-first.js'
    }
    if (namesMap[name]){
        return namesMap[name]
    }
    return name
}


```

