```ts
createApp({ render: () => h(App, props) })
    .use(plugin)
    .use(ZiggyVue)
    .use({
        install(app) {
            const routeFn = (...args: Parameters<typeof route>) => route(args[0], args[1], args[2] ?? false, args[3]);

            app.provide('route', routeFn);
            app.config.globalProperties.route = routeFn;
        },
    })
    .use(ui)
    .mount(el);
```

