Sharing my current composable here in case it’s useful. Happy to hear if you have ideas to improve it.

```ts
import type { Table } from '@tanstack/vue-table'
import type { TableRow } from '@nuxt/ui'

export function useTableUtils<T>() {
  const rowSelection = ref<Record<string, boolean>>({})
  const lastSelectedRowIndex = ref<number>()

  function handleShiftSelect(tableApi: Table<T>, row: TableRow<T>, isShift: boolean, shouldToggle: boolean = false) {
    const rows = tableApi?.getRowModel().rows
    if (!rows) return
    const currentIndex = rows.findIndex(r => r.id === row.id)
    if (isShift && lastSelectedRowIndex.value !== undefined) {
      const start = Math.min(lastSelectedRowIndex.value, currentIndex)
      const end = Math.max(lastSelectedRowIndex.value, currentIndex)
      for (let i = start; i <= end; i++) {
        const rowId = rows[i]?.id || ''
        rowSelection.value[rowId] = true
      }
    } else if (!isShift && shouldToggle) {
      row.toggleSelected(!row.getIsSelected())
    }
    lastSelectedRowIndex.value = currentIndex
  }

  return {
    handleShiftSelect,
    rowSelection,
    lastSelectedRowIndex
  }
}
```

