Boy, I'm glad I stumbled across this thread. I too just abandoned shadcn's drawer because the vaul-vue dependency just simply does not work. This thread inspired me to come up with my own component. 

If anybody wants a drawer component that just uses reka-ui `Dialog` and vueUse `usePointerSwipe`, I've got this so far and seems to work somewhat fine (at least better than the vaul-vue drawer). Any improvements or criticism would be appreciated, or if you wanna use it as a jumping off point, go for it. (Disclaimer: used Gemini Pro a bit to help)

```
<script setup lang="ts">
import { usePointerSwipe, useWindowSize } from '@vueuse/core'
import { DialogRoot, DialogPortal, DialogContent, DialogOverlay } from 'reka-ui'

const VELOCITY_THRESHOLD = 0.75 // px/ms. Tweak this higher/lower to change sensitivity of fast swipe detection

const isOpen = defineModel<boolean>('open', { default: false })
const activeSnapPoint = defineModel<number>('activeSnapPoint')

const props = withDefaults(defineProps<{
  snapPoints?: number[]
  dismissible?: boolean
  modal?: boolean
}>(), {
  snapPoints: () => [0.2, 0.5],
  dismissible: false,
  modal: false
})

const { height: windowHeight } = useWindowSize()

const currentHeight = useState('drawerHeight', () => 0)
const maxHeight = useState('drawerMaxHeight', () => 0)

const drawerRef = ref<HTMLElement | null>(null)
const handleRef = ref<HTMLElement | null>(null)

const isDragging = ref(false)
const initialHeight = ref(0) 
const isIgnoringSwipe = ref(false) // To track if the current gesture should be ignored, use data-ignore-swipe on any element

let lastTime = 0
let lastHeight = 0
let swipeVelocity = 0

watchEffect(() => {
  const highestSnap = props.snapPoints[props.snapPoints.length - 1] ?? 0
  maxHeight.value = windowHeight.value * highestSnap
})

const { distanceY } = usePointerSwipe(drawerRef, {
  onSwipeStart(event) {
    const target = event.target as HTMLElement
    if (target.closest('[data-swipe-ignore]')) {
      isIgnoringSwipe.value = true
      return
    }

    isIgnoringSwipe.value = false
    isDragging.value = true
    initialHeight.value = currentHeight.value 

    // 1. Initialize velocity tracking on start
    lastTime = performance.now()
    lastHeight = initialHeight.value
    swipeVelocity = 0
  },

  onSwipe() {
    if (isIgnoringSwipe.value) return

    let newHeight = initialHeight.value + distanceY.value

    if (newHeight > maxHeight.value) {
      newHeight = maxHeight.value + (newHeight - maxHeight.value) * 0.15 
    }

    currentHeight.value = newHeight

    // 2. Calculate instantaneous velocity during the swipe
    const now = performance.now()
    const deltaTime = now - lastTime

    // Update velocity roughly every frame (~16ms) to avoid divide-by-zero jitter
    if (deltaTime > 8) { 
      swipeVelocity = (newHeight - lastHeight) / deltaTime // px per millisecond
      lastTime = now
      lastHeight = newHeight
    }
  },

  onSwipeEnd() {
    if (isIgnoringSwipe.value) {
      isIgnoringSwipe.value = false 
      return
    }

    isDragging.value = false
    const currentPercent = currentHeight.value / windowHeight.value

    if (props.dismissible && currentPercent < (props.snapPoints?.[0] ?? 0) - 0.08) {
      isOpen.value = false
      return
    }

    // 3. Nullify velocity if the user paused before letting go
    if (performance.now() - lastTime > 50) {
      swipeVelocity = 0
    }

    // 4. Determine the target snap point
    let closest: number;

    // Ensure snap points are sorted from lowest to highest for the logic to work
    const sortedSnaps = [...props.snapPoints].sort((a, b) => a - b)

    if (Math.abs(swipeVelocity) > VELOCITY_THRESHOLD) {
      // FAST SWIPE: Find the next point in the direction of the swipe
      if (swipeVelocity > 0) {
        // Swiping UP: Find the first point greater than the current position
        closest = sortedSnaps.find(p => p > currentPercent) ?? sortedSnaps[sortedSnaps.length - 1] ?? 0
      } else {
        // Swiping DOWN: Find the first point lesser than the current position
        closest = [...sortedSnaps].reverse().find(p => p < currentPercent) ?? sortedSnaps[0] ?? 0
      }
    } else {
      // SLOW SWIPE: Fall back to your original "closest distance" logic
      closest = sortedSnaps.reduce((prev, curr) => {
        return Math.abs(curr - currentPercent) < Math.abs(prev - currentPercent) ? curr : prev
      })
    }

    activeSnapPoint.value = closest
    currentHeight.value = windowHeight.value * closest
  },
})

const drawerStyle = computed(() => ({
  height: `${currentHeight.value}px`,
  transition: isDragging.value ? 'none' : 'height 0.4s cubic-bezier(0.32, 0.72, 0, 1)'
}))

const handleCloseAttempt = (event: Event) => {
  if (!props.dismissible) {
    event.preventDefault()
  }
}

const setInitialHeight = () => {
    if (!activeSnapPoint.value || !props.snapPoints.includes(activeSnapPoint.value)) {
      activeSnapPoint.value = props.snapPoints[0]!
    }
    currentHeight.value = windowHeight.value * activeSnapPoint.value
}

watch(activeSnapPoint, (newVal) => {
  if (newVal && isOpen.value && !isDragging.value) {
    currentHeight.value = windowHeight.value * newVal
  }
})

watch(isOpen, (newVal) => {
  if (newVal) {
    setInitialHeight()
  }
})

onMounted(() => {
  if (isOpen.value) {
    setInitialHeight()
  }
})
</script>


<template>
    <DialogRoot v-model:open="isOpen" :modal="props.modal">
        <DialogPortal>
            <DialogOverlay 
                v-if="props.modal" 
                class="drawer-overlay fixed inset-0 bg-black/40 z-40" 
            />

            <DialogContent 
                class="drop-shadow-2xl"
                as-child 
                @interact-outside="handleCloseAttempt" 
                @escape-keydown="handleCloseAttempt"
            >
                <div
                    ref="drawerRef"
                    :style="drawerStyle"
                    class="drawer-content fixed bottom-0 left-0 right-0 bg-background border-t shadow-3xl z-50 rounded-t-3xl flex flex-col touch-none"
                >
                    <div ref="handleRef" class="w-full pt-4 flex justify-center items-center cursor-grab active:cursor-grabbing shrink-0 group">
                        <div class="w-24 h-1.5 bg-slate-400 rounded-full group-hover:bg-slate-400 group-active:bg-slate-500 transition-colors" />
                    </div>

                    <slot />

                </div>
            </DialogContent>
        </DialogPortal>
    </DialogRoot>
</template>
<style scoped>
/* Overlay Fade In/Out */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes fadeOut {
  from { opacity: 1; }
  to { opacity: 0; }
}
.drawer-overlay[data-state='open'] {
  animation: fadeIn 0.3s ease-out;
}
.drawer-overlay[data-state='closed'] {
  animation: fadeOut 0.3s ease-in;
}

/* Drawer Slide In/Out */
@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}
@keyframes slideDown {
  from { transform: translateY(0); }
  to { transform: translateY(100%); }
}
.drawer-content[data-state='open'] {
  animation: slideUp 0.4s cubic-bezier(0.32, 0.72, 0, 1); 
}
.drawer-content[data-state='closed'] {
  animation: slideDown 0.4s cubic-bezier(0.32, 0.72, 0, 1);
}
</style>
```

I used VueUse [useSwipe](https://vueuse.org/core/useSwipe/) to close the slideover/dialog:

```ts
import { useSwipe } from '@vueuse/core';

// Close on swipe
const isOpen = ref(false);
const dialogContentRef = useTemplateRef<HTMLElement>('dialog-content');
const { isSwiping, direction } = useSwipe(dialogContentRef);

watch(isSwiping, () => {
  if (direction.value === props.side) {
    isOpen.value = false;
  }
});
```

I think the drag-to-close is a really nice nice-to-have, but it is unnecessary for a good and working UX. Closing on swipe however is crucial and should be added (as a default) to (current) Slideover.

