                    color: "text-muted", // Muted color for miss-out features (paid plan has unlimited projects)
                },
                {
                    title: "Limited Platforms",
                    color: "text-muted",
                    tooltip: "Desktop only. Android & iOS not included.", // Additional details
                },
            ],
            [
                {
                    title: "Common Features",
                    type: "label",
                },
                {
                    title: "Common features",
                },
